async function pageFunction(context) {
    const { page, request } = context;
    await page.waitForTimeout(12000);
    try { await page.mouse.wheel(0, 2500); } catch (e) {}
    await page.waitForTimeout(6000);
    const data = await page.evaluate(() => {
        const re = /(chat|assist|bot\b|chatbot|genie|copilot|\bki\b|\bai\b|ask|messenger|intercom|zendesk|hubspot|drift|userlike|livechat|tawk|freshchat|crisp|tidio|salesforce|kustomer|gorgias|ada\.|botpress|voiceflow|helpwise|smartsupp|moin|onlim|kauz|ze-snippet|olark|liveperson|sprinklr|cognigy|parloa|zoovu)/i;
        const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src).filter(s => re.test(s));
        const iframes = Array.from(document.querySelectorAll('iframe')).map(f => ({src: f.src || '', title: f.title || '', id: f.id || '', name: f.name || ''})).filter(f => re.test(f.src + ' ' + f.title + ' ' + f.id + ' ' + f.name));
        const els = [];
        document.querySelectorAll('[id],[class],[aria-label],button,a').forEach(el => {
            const id = el.id || '';
            const cls = (typeof el.className === 'string') ? el.className : '';
            const aria = el.getAttribute('aria-label') || '';
            const txt = (el.innerText || '').trim().slice(0, 80);
            const hay = id + ' ' + cls + ' ' + aria + ' ' + (el.tagName === 'BUTTON' || el.tagName === 'A' ? txt : '');
            if (/(chat|assistant|assistent|chatbot|\bki-|ai-assist|ask-ai|copilot|messenger|live-?chat|helpbot|genie)/i.test(hay)) {
                const r = el.getBoundingClientRect();
                els.push({tag: el.tagName, id: id.slice(0, 60), cls: cls.slice(0, 120), aria: aria.slice(0, 80), text: txt, visible: r.width > 0 && r.height > 0, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height)});
            }
        });
        const globals = ['Intercom','zE','HubSpotConversations','drift','userlike','LiveChatWidget','Tawk_API','fcWidget','$crisp','tidioChatApi','Kustomer','embedded_svc','ada','voiceflow','botpress','smartsupp','Zoovu'].filter(g => typeof window[g] !== 'undefined');
        return {title: document.title, lang: document.documentElement.lang, scripts: scripts.slice(0, 40), iframes: iframes.slice(0, 20), elements: els.slice(0, 40), globals, viewport: {w: window.innerWidth, h: window.innerHeight}};
    });
    return { url: request.url, loadedUrl: page.url(), loadedAt: new Date().toISOString(), ...data };
}
